for s in "${scripts[@]}"; do
  script="webui/scripts/${s}.sh"
  if [[ ! -x "$script" ]]; then
    echo "SKIP $s (missing)"
    continue
  fi
  echo "===== $s ====="
  if bash "$script"; then
    echo "OK $s"
  else
    echo "FAIL $s"
    fail=1
    break
  fi
done

if [[ "$fail" -ne 0 ]]; then
  echo "E2E suite FAILED"
  exit 1
fi
echo "OK: full e2e suite passed"
